315  void Utils::unescapeStringToBuffer(const char* data, v_buff_size size, p_char8 resultData){
   316
   317    v_buff_size i = 0;
   318    v_buff_size pos = 0;
   319
   320    while (i < size) {
   321      v_char8 a = static_cast<v_char8>(data[i]);
   322
   323      if(a == '\\'){
   324        v_char8 b = static_cast<v_char8>(data[i + 1]);
   325        if(b != 'u'){
   326          switch (b) {
   327            case '"': resultData[pos] = '"'; pos ++; break;
   328            case '\\': resultData[pos] = '\\'; pos ++; break;
   329            case '/': resultData[pos] = '/'; pos ++; break;
   330            case 'b': resultData[pos] = '\b'; pos ++; break;
   331            case 'f': resultData[pos] = '\f'; pos ++; break;
   332            case 'n': resultData[pos] = '\n'; pos ++; break;
   333            case 'r': resultData[pos] = '\r'; pos ++; break;
   334            case 't': resultData[pos] = '\t'; pos ++; break;
   335            default: break;
   336          }
   337          i += 2;
   338        } else {
   339          if(data[i + 2] == '+'){ // Not JSON standard case
   340            v_uint32 code;
   341            encoding::Hex::readUInt32(&data[i + 3], code);
   342            i += 11;
   343            pos += encoding::Unicode::decodeUtf8Char(static_cast<v_int32>(code), &resultData[pos]);
   344          } else {
   345
   346            v_uint16 code;
   347            encoding::Hex::readUInt16(&data[i + 2], code);
   348
   349            if(code >= 0xD800 && code <= 0xDBFF){
   350              v_uint16 low;
   351              encoding::Hex::readUInt16(&data[i + 8], low);
   352              v_uint32 bigCode = static_cast<v_uint32>(encoding::Unicode::utf16SurrogatePairToCode(static_cast<v_int16>(code), static_cast<v_int16>(low)));
   353              pos += encoding::Unicode::decodeUtf8Char(static_cast<v_int32>(bigCode), &resultData[pos]);
   354              i += 12;
   355            } else {
   356              pos += encoding::Unicode::decodeUtf8Char(code, &resultData[pos]);
   357              i += 6;
   358            }
   359
   360          }
   361        }
   362      } else {
   363        resultData[pos] = a;
   364        pos ++;
   365        i++;
   366      }
   367
   368    }
   369
   370  }
